DROP TABLE IF EXISTS `movimiento_caja`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `movimiento_caja` (
  `ID_MOVIMIENTO` int(11) NOT NULL AUTO_INCREMENT,
  `ID_USUARIO` int(11) NOT NULL,
  `ID_SUCURSAL` int(11) NOT NULL,
  `ID_FACTURA` int(11) DEFAULT NULL,
  `TIPO_MOVIMIENTO` enum('INGRESO','EGRESO') NOT NULL,
  `METODO_PAGO` enum('EFECTIVO','TRANSFERENCIA','TARJETA') NOT NULL,
  `MONTO` decimal(10,2) NOT NULL,
  `CONCEPTO` varchar(100) NOT NULL,
  `FECHA_HORA` datetime DEFAULT CURRENT_TIMESTAMP,
  `CODIGO_MOVIMIENTO` varchar(50) DEFAULT NULL,
  `ORIGEN_MOVIMIENTO` varchar(50) DEFAULT 'MOVIMIENTOS CAJA',
  `TIPO_EGRESO` varchar(100) DEFAULT NULL,
  `ESTADO_APROBACION` varchar(20) DEFAULT 'POR_APROBAR',
  `MOTIVO_RECHAZO` text,
  PRIMARY KEY (`ID_MOVIMIENTO`),
  KEY `ID_USUARIO` (`ID_USUARIO`),
  KEY `ID_SUCURSAL` (`ID_SUCURSAL`),
  KEY `ID_FACTURA` (`ID_FACTURA`),
  CONSTRAINT `movimiento_caja_ibfk_1` FOREIGN KEY (`ID_USUARIO`) REFERENCES `usuario` (`ID_USUARIO`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `movimiento_caja_ibfk_2` FOREIGN KEY (`ID_SUCURSAL`) REFERENCES `sucursal` (`ID_SUCURSAL`) ON DELETE RESTRICT ON UPDATE CASCADE,
  CONSTRAINT `movimiento_caja_ibfk_3` FOREIGN KEY (`ID_FACTURA`) REFERENCES `factura` (`ID_FACTURA`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=65 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
