  `CODIGO_SOCIO` varchar(50) DEFAULT NULL,
  `OBSERVACION` varchar(255) DEFAULT NULL,
  `PAX_MENOR` varchar(15) DEFAULT NULL,
  `PAX_PET` varchar(15) DEFAULT NULL,
  `ID_FACTURA_SOBREPESO` int(11) DEFAULT NULL,
  `ID_RUTA_TRAMO_SOBREPESO` int(11) DEFAULT NULL,
  PRIMARY KEY (`ID_PASAJE`),
  KEY `ID_FACTURA` (`ID_FACTURA`),
  KEY `ID_BUS` (`ID_BUS`),
  CONSTRAINT `pasaje_ibfk_1` FOREIGN KEY (`ID_FACTURA`) REFERENCES `factura` (`ID_FACTURA`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `pasaje_ibfk_2` FOREIGN KEY (`ID_BUS`) REFERENCES `bus` (`ID_BUS`) ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=23 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
